const j=$input.first().json;
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0')+'-'+s.length;};
if(!Array.isArray(j.characters)||!j.characters.length) throw new Error('characters must be a non-empty array');
const channel=String(j.channel_id||''); if(!channel) throw new Error('channel_id required for quota enforcement');
const daily=Number(j.account_daily_quota); if(!Number.isInteger(daily)||daily<1||daily>20) throw new Error('account_daily_quota must be a verified integer in 1..20');
const count=Number(j.ads_per_character); if(!Number.isInteger(count)||count<1) throw new Error('ads_per_character must be positive');
const max=Math.min(daily,Number(j.run_cap||daily)); if(count*j.characters.length>max) throw new Error('Requested batch exceeds run/account quota');
const seen=new Set(),out=[]; for(const c of j.characters){ if(!c.character_id||!c.ad_concept||c.fictional_adult!==true) throw new Error('Require stable character_id, ad_concept, fictional_adult=true'); const identity=String(c.character_id); for(let i=0;i<count;i++){ const key=identity+'|'+String(c.ad_concept).trim().toLowerCase()+'|'+i; if(seen.has(key)) continue; seen.add(key); out.push({json:{asset_id:hash(key),character_id:identity,channel_id:channel,concept:c.ad_concept,variation:i+1,provenance:{source_id:'DdOIy0DsPCK',source_url:'https://www.instagram.com/alexhustleshard/reel/DdOIy0DsPCK/'},generation:'PENDING_CONFIGURED_MEDIA_WORKER',quality_gate:['identity_consistency','originality','claims','platform_quota'],review_status:'needs_human_review',publish_status:'disabled'}}); } }
return out;
